+  --bg: #0b1020;
+  --bg-2: #111a30;
+  --panel: #141f3a;
+  --panel-2: #18264a;
+  --border: #24345c;
+  --text: #dce6ff;
+  --muted: #8294bd;
+  --closed: #2ecc8f;
+  --open: #ff5470;
+  --half: #ffb340;
+  --accent: #4d8dff;
+  --warn: #ffb340;
+  --danger: #ff5470;
+  --good: #2ecc8f;
+  --mono: ui-monospace, "Cascadia Mono", Consolas, "SF Mono", monospace;
+}
+
+* { box-sizing: border-box; }
+
+html, body {
+  margin: 0;
+  padding: 0;
+  background: radial-gradient(1200px 700px at 70% -10%, #16244a 0%, var(--bg) 55%);
+  color: var(--text);
+  font-family: system-ui, -apple-system, "Segoe UI", "Microsoft YaHei", sans-serif;
+  font-size: 14px;
+}
+
+/* ---------------- top bar ---------------- */
+.topbar {
+  display: flex;
+  align-items: center;
+  justify-content: space-between;
+  padding: 12px 20px;
+  border-bottom: 1px solid var(--border);
+  background: rgba(10, 16, 34, 0.85);
+  position: sticky;
+  top: 0;
+  z-index: 10;
+  backdrop-filter: blur(6px);
+}
+.brand { display: flex; align-items: center; gap: 12px; }
+.logo {
+  font-size: 30px;
+  color: var(--accent);
+  text-shadow: 0 0 14px rgba(77, 141, 255, 0.7);
+}
+.topbar h1 { font-size: 17px; margin: 0; letter-spacing: 0.5px; }
+.topbar p { margin: 2px 0 0; color: var(--muted); font-size: 12px; }
+.conn { display: flex; align-items: center; gap: 8px; color: var(--muted); }
+.dot { width: 10px; height: 10px; border-radius: 50%; display: inline-block; }
+.dot-on { background: var(--good); box-shadow: 0 0 10px var(--good); }
+.dot-off { background: var(--danger); box-shadow: 0 0 10px var(--danger); }
+
+/* ---------------- layout ---------------- */
+.layout {
+  display: grid;
+  grid-template-columns: minmax(0, 1fr) 380px;
+  gap: 14px;
+  padding: 14px;
+  align-items: start;
+}
+.col { display: flex; flex-direction: column; gap: 14px; min-width: 0; }
+
+.panel {
+  background: linear-gradient(180deg, var(--panel) 0%, var(--bg-2) 100%);
+  border: 1px solid var(--border);
+  border-radius: 12px;
+  padding: 14px;
+  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.25);
+}
+.panel-head {
+  display: flex;
+  align-items: center;
+  justify-content: space-between;
+  margin-bottom: 10px;
+}
+.panel-head h2 { font-size: 14px; margin: 0; color: #b9ccff; letter-spacing: 0.5px; }
+
+/* ---------------- topology ---------------- */
+.topology-panel { position: relative; }
+#topo {
+  width: 100%;
+  height: auto;
+  display: block;
+  border-radius: 8px;
+  background:
+    linear-gradient(rgba(77, 141, 255, 0.05) 1px, transparent 1px) 0 0 / 34px 34px,
+    linear-gradient(90deg, rgba(77, 141, 255, 0.05) 1px, transparent 1px) 0 0 / 34px 34px,
+    #0c1428;
+}
+.legend { display: flex; gap: 14px; color: var(--muted); font-size: 12px; }
+.legend span { display: inline-flex; align-items: center; gap: 5px; }
+.sw { width: 10px; height: 10px; border-radius: 3px; display: inline-block; }
+.sw-closed { background: var(--closed); }
+.sw-open { background: var(--open); }
+.sw-half { background: var(--half); }
+
+.phase-banner {
+  position: absolute;
+  left: 50%;
+  top: 52px;
+  transform: translateX(-50%);
+  background: rgba(18, 32, 66, 0.95);
+  border: 1px solid var(--accent);
+  color: #dfe9ff;
+  padding: 10px 22px;
+  border-radius: 999px;
+  font-size: 14px;
+  box-shadow: 0 0 24px rgba(77, 141, 255, 0.45);
+  white-space: nowrap;
+}
+.phase-banner b { color: var(--accent); }
+
+/* ---------------- logs ---------------- */
+.log-panel { min-height: 230px; }
+.log-tools { display: flex; gap: 10px; align-items: center; }
+.chk { color: var(--muted); font-size: 12px; display: flex; gap: 4px; align-items: center; }
+.log-box {
+  height: 240px;
+  overflow-y: auto;
+  background: #0a1122;
+  border: 1px solid var(--border);
+  border-radius: 8px;
+  padding: 8px 10px;
+  font-family: var(--mono);
+  font-size: 12px;
+  line-height: 1.65;
+}
+.log-line { white-space: pre-wrap; }
+.log-line .t { color: #6377a5; margin-right: 8px; }
+.log-info { color: #b9ccff; }
+.log-warn { color: var(--warn); }
+.log-error { color: var(--danger); }
+.log-debug { color: #5e719c; }
+.log-line .tag {
+  display: inline-block;
+  min-width: 92px;
+  color: #7fa0e8;
+}
+
+/* ---------------- buttons / controls ---------------- */
+.btn {
+  background: var(--panel-2);
+  color: var(--text);
+  border: 1px solid var(--border);
+  border-radius: 8px;
+  padding: 8px 12px;
+  font-size: 13px;
+  cursor: pointer;
+  transition: transform 0.08s ease, box-shadow 0.15s ease, border-color 0.15s;
+}
+.btn:hover { border-color: var(--accent); box-shadow: 0 0 12px rgba(77, 141, 255, 0.35); }
+.btn:active { transform: translateY(1px); }
+.btn:disabled { opacity: 0.45; cursor: not-allowed; box-shadow: none; }
+.btn-mini { padding: 4px 10px; font-size: 12px; }
+.btn-primary {
+  background: linear-gradient(180deg, #3f7dff, #2d5fd6);
+  border-color: #3f7dff;
+  width: 100%;
+  font-weight: 600;
+}
+.btn-danger { background: linear-gradient(180deg, #e84763, #c62f49); border-color: #e84763; }
+.btn-warn { background: #3a2e15; border-color: #6b511c; color: #ffd791; }
+.btn-good { background: #123829; border-color: #1e6b4a; color: #9ff0cd; }
+.demo-controls { display: flex; flex-direction: column; gap: 8px; }
+
+.demo-steps {
+  margin: 12px 0 0;
+  padding-left: 20px;
+  color: var(--muted);
+  font-size: 12.5px;
+  line-height: 2;
+}
+.demo-steps li { transition: color 0.2s; border-radius: 4px; padding-left: 4px; }
+.demo-steps li.active { color: var(--accent); font-weight: 600; }
+.demo-steps li.done { color: var(--good); }
+.demo-steps li.active::after { content: "  ← 进行中"; font-size: 11px; }
+
+.controls { display: flex; flex-direction: column; gap: 12px; }
+.ctl-row label { display: block; color: var(--muted); font-size: 12px; margin-bottom: 5px; }
+.inline { display: flex; align-items: center; gap: 8px; }
+.inline input[type="range"] { flex: 1; accent-color: var(--accent); }
+.num { font-family: var(--mono); min-width: 34px; text-align: right; color: #a9c2ff; }
+input[type="number"], select {
+  width: 100%;
+  background: #0c1428;
+  color: var(--text);
+  border: 1px solid var(--border);
+  border-radius: 8px;
+  padding: 7px 10px;
+  font-size: 13px;
+}
+.btn-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; }
+
+/* ---------------- chart + kpis ---------------- */
+#chart {
+  width: 100%;
+  height: 120px;
+  display: block;
+  background: #0c1428;
+  border: 1px solid var(--border);
+  border-radius: 8px;
+}
+.kpis {
+  display: grid;
+  grid-template-columns: repeat(3, 1fr);
+  gap: 8px;
+  margin-top: 10px;
+}
+.kpi {
+  background: #0e1830;
+  border: 1px solid var(--border);
+  border-radius: 8px;
+  padding: 8px;
+  text-align: center;
+}
+.kpi .v { font-family: var(--mono); font-size: 17px; color: #dce6ff; }
+.kpi .l { font-size: 11px; color: var(--muted); margin-top: 2px; }
+.kpi.good .v { color: var(--good); }
+.kpi.warn .v { color: var(--warn); }
+.kpi.bad .v { color: var(--danger); }
+
+/* ---------------- node cards ---------------- */
+.node-cards { display: flex; flex-direction: column; gap: 8px; max-height: 340px; overflow-y: auto; }
+.node-card {
+  border: 1px solid var(--border);
+  border-left-width: 4px;
+  border-radius: 8px;
+  padding: 8px 10px;
+  background: #0e1830;
+}
+.node-card.st-CLOSED { border-left-color: var(--closed); }
+.node-card.st-OPEN { border-left-color: var(--open); }
+.node-card.st-HALF_OPEN { border-left-color: var(--half); }
+.nc-head { display: flex; justify-content: space-between; align-items: center; }
+.nc-name { font-weight: 600; font-size: 13px; }
+.nc-state {
+  font-size: 11px;
+  padding: 2px 8px;
+  border-radius: 999px;
+  font-weight: 600;
+}
+.nc-state.st-CLOSED { background: rgba(46, 204, 143, 0.15); color: var(--closed); }
+.nc-state.st-OPEN { background: rgba(255, 84, 112, 0.15); color: var(--open); }
+.nc-state.st-HALF_OPEN { background: rgba(255, 179, 64, 0.15); color: var(--half); }
+.nc-grid {
+  display: grid;
+  grid-template-columns: repeat(3, 1fr);
+  gap: 4px 8px;
+  margin-top: 7px;
+  font-size: 11.5px;
+  color: var(--muted);
+}
+.nc-grid b { color: #c9d8ff; font-family: var(--mono); font-weight: 600; }
+.bar {
+  height: 5px;
+  border-radius: 3px;
+  background: #1c2b50;
+  margin-top: 7px;
+  overflow: hidden;
+}
+.bar > i { display: block; height: 100%; border-radius: 3px; transition: width 0.3s; }
+
+.hidden { display: none !important; }
+
+/* ---------------- scrollbars ---------------- */
+::-webkit-scrollbar { width: 8px; height: 8px; }
+::-webkit-scrollbar-thumb { background: #2a3c6b; border-radius: 8px; }
+::-webkit-scrollbar-track { background: transparent; }
+
+@media (max-width: 1100px) {
+  .layout { grid-template-columns: 1fr; }
+}
*** End Patch
'@
[System.IO.File]::WriteAllText("$PWD\p.tmp", $p.Replace("`r`n","`n"), (New-Object System.Text.UTF8Encoding($false)))
python ap.py p.tmp"}

